import {t} from './i18n.js?v=procedures-unified-20261008';
export function accuracyDonut(correct,total){const p=total?Math.round(correct/total*100):0;return `<figure class="stats-donut"><svg viewBox="0 0 120 120" role="img" aria-label="${t('stats.accuracy')}: ${p}%"><circle class="donut-track" cx="60" cy="60" r="46"/><circle class="donut-value" cx="60" cy="60" r="46" pathLength="100" stroke-dasharray="${p} 100" transform="rotate(-90 60 60)"/><text x="60" y="64" text-anchor="middle">${p}%</text></svg><figcaption>${correct} ${t('stats.correct')} · ${total-correct} ${t('stats.errors')}</figcaption></figure>`}
export function comparisonBars(before,after){return `<div class="comparison-bars" role="img" aria-label="${t('stats.comparison')}: ${before}% / ${after}%">${[[t('stats.villain'),before],[t('stats.hero'),after]].map(([label,value])=>`<div><span>${label}</span><div class="chart-bar"><i style="width:${value}%"></i></div><strong>${value}%</strong></div>`).join('')}<p>0% <span>100%</span></p></div>`}
export function xpLine(days){const data=[...days].sort((a,b)=>a.day.localeCompare(b.day)).slice(-14),max=Math.max(1,...data.map(x=>x.xp));const points=data.map((d,i)=>({x:data.length===1?160:24+i*272/(data.length-1),y:120-d.xp/max*90,...d}));return `<figure class="stats-line"><svg viewBox="0 0 320 150" role="img" aria-label="${t('xp.dailyTrend')}"><path class="chart-grid" d="M24 30H296 M24 75H296 M24 120H296"/><text class="chart-axis" x="24" y="18">${max} XP</text>${points.length>1?`<polyline points="${points.map(p=>p.x+','+p.y).join(' ')}"/>`:''}${points.map(p=>`<circle cx="${p.x}" cy="${p.y}" r="4" role="button" tabindex="0" data-xp-point="${p.day}: ${p.xp} XP" aria-label="${p.day}: ${p.xp} XP"><title>${p.day}: ${p.xp} XP</title></circle>`).join('')}<text class="chart-axis" x="24" y="143">${data[0]?.day||'—'}</text><text class="chart-axis" x="296" y="143" text-anchor="end">${data.at(-1)?.day||'—'}</text></svg><figcaption>${data.length?t('xp.dailyNote'):t('stats.empty')}</figcaption></figure>`}

function inspectPoint(event){const point=event.target.closest('[data-xp-point]');if(!point)return;if(event.type==='keydown'&&!['Enter',' '].includes(event.key))return;if(event.type==='keydown')event.preventDefault();point.closest('figure').querySelector('figcaption').textContent=point.dataset.xpPoint;}
document.addEventListener('click',inspectPoint);document.addEventListener('keydown',inspectPoint);
